-- ─────────────────────────────────────────────────────────────────────────────
-- AI Workout Plan DDL
--
-- Stores the personalised workout plan generated by ChatGPT for each user.
-- One row = one exercise slot for one day.
-- Generated once on profile creation; can be regenerated via
--   POST /ai-plan/generate?userId={id}
-- ─────────────────────────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS public.ai_workout_plan (
    id              BIGSERIAL PRIMARY KEY,
    user_id         BIGINT        NOT NULL,
    day_number      INTEGER       NOT NULL,
    day_name        VARCHAR(255),
    exercise_library_id BIGINT    REFERENCES public.exercise_library(id) ON DELETE SET NULL,
    muscle_group    VARCHAR(100),
    sets            INTEGER,
    rep_min         INTEGER,
    rep_max         INTEGER,
    created_at      TIMESTAMPTZ   NOT NULL DEFAULT NOW()
);

-- Index for fast lookups by user + day (most common query pattern)
CREATE INDEX IF NOT EXISTS idx_ai_workout_plan_user_day
    ON public.ai_workout_plan (user_id, day_number);

-- Index for full-plan retrieval ordered by day
CREATE INDEX IF NOT EXISTS idx_ai_workout_plan_user
    ON public.ai_workout_plan (user_id);

-- ─────────────────────────────────────────────────────────────────────────────
-- How to use after running this DDL:
--
-- 1. Run this SQL in your Supabase SQL editor.
-- 2. Restart the Spring Boot app.
-- 3. On new profile creation the plan is generated automatically (async).
-- 4. To generate/regenerate for an existing user:
--      POST /ai-plan/generate?userId={userId}
-- 5. To view the stored plan:
--      GET  /ai-plan/{userId}
-- 6. To delete and force regeneration:
--      DELETE /ai-plan/{userId}
--      POST   /ai-plan/generate?userId={userId}
-- ─────────────────────────────────────────────────────────────────────────────

